code.snippet:
body.t-botanical .hero h1 { color: #2e3b2f; }
body.t-botanical .tagline { color: #5f7f5a; font-style: italic; }
body.t-botanical .section-tag { background: #eef1e5; border-color: rgba(95,127,90,.3); border-radius: 99px 99px 99px 4px; }
body.t-botanical .section-title::after { content: "❧"; color: var(--accent); font-size: .6em; margin-left: 12px; opacity: .7; }
body.t-botanical .card { border-radius: 28px 28px 28px 8px; border-color: rgba(95,127,90,.22); }
body.t-botanical .card:nth-child(even) { border-radius: 28px 28px 8px 28px; }
body.t-botanical .card.featured { border-color: #5f7f5a; border-width: 2px; }
body.t-botanical .card.featured::before { background: #5f7f5a; }
body.t-botanical .btn { border-radius: 99px 99px 99px 12px; }
body.t-botanical .btn-primary { background: #5f7f5a; color: #f4f5ef; }
body.t-botanical .btn-primary:hover { background: #4d6a49; }
body.t-botanical .btn-ghost { border-color: rgba(95,127,90,.35); }
body.t-botanical .btn-ghost:hover { border-color: #5f7f5a; }
body.t-botanical .lang { border-radius: 99px 99px 99px 6px; }
body.t-botanical .tag { border-radius: 99px 99px 99px 8px; border-color: rgba(95,127,90,.3); }
body.t-botanical .tag:hover { background: #5f7f5a; color: #f4f5ef; border-color: #5f7f5a; }
body.t-botanical .bar-track { background: #e2e7d6; height: 10px; }
body.t-botanical .bar-fill { background: linear-gradient(90deg, #5f7f5a, #8faa87); }
body.t-botanical .bar-row:nth-child(2) .bar-fill { background: linear-gradient(90deg, #c9a86a, #dcc48f); }
body.t-botanical .hero-badge { border-color: rgba(95,127,90,.35); border-radius: 99px 99px 99px 8px; }
body.t-botanical .hero-badge i { background: #5f7f5a; border-radius: 50% 50% 50% 0; animation: none; }
